package com.marketplace.customer;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.cache.annotation.*; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.net.URI; import java.util.*;
@RestController @RequestMapping("/api/customers") class CustomerController { private final CustomerRepository repo; CustomerController(CustomerRepository r){repo=r;} record Request(@NotBlank String name,@Email String email,@NotBlank String document){} record View(Long id,String name,String email,String document){static View of(Customer c){return new View(c.id,c.name,c.email,c.document);}} @GetMapping @Cacheable("customers") List<View> list(){return repo.findAll().stream().map(View::of).toList();} @GetMapping("/{id}") @Cacheable(value="customer",key="#id") View get(@PathVariable Long id){return View.of(repo.findById(id).orElseThrow(()->new NoSuchElementException("Cliente não encontrado")));} @PostMapping ResponseEntity<View> create(@Valid @RequestBody Request r){var c=repo.save(new Customer(r.name(),r.email(),r.document()));return ResponseEntity.created(URI.create("/api/customers/"+c.id)).body(View.of(c));} @PutMapping("/{id}") @CacheEvict(value={"customer","customers"},allEntries=true) View update(@PathVariable Long id,@Valid @RequestBody Request r){var c=repo.findById(id).orElseThrow();c.name=r.name();c.email=r.email();c.document=r.document();return View.of(repo.save(c));} }
